Dataspatium.assets.register("presets/api/boverket-energideklarationer.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"boverket-energideklarationer\",\n  \"name\": \"Boverket energideklarationer\",\n  \"publisher\": \"Boverket\",\n  \"description\": \"Energideklarationer för byggnader via Boverkets API. Kräver en prenumerationsnyckel från Boverkets API-portal. Anropen beskrivs i portalen; ange sökväg och parametrar här.\",\n  \"docs\": \"https://api-portal.boverket.se/\",\n  \"license\": { \"name\": \"Se villkor i Boverkets API-portal\", \"url\": \"https://api-portal.boverket.se/\" },\n  \"level\": 2,\n  \"country\": \"SE\",\n  \"baseUrl\": \"https://api.boverket.se/energideklarationer\",\n  \"auth\": {\n    \"type\": \"apiKey\",\n    \"in\": \"header\",\n    \"name\": \"Ocp-Apim-Subscription-Key\",\n    \"help\": \"Registrera dig i Boverkets API-portal och prenumerera på API:et för energideklarationer. Nyckeln finns under din profil i portalen.\",\n    \"signupUrl\": \"https://api-portal.boverket.se/\"\n  },\n  \"rateLimit\": { \"requests\": 10, \"perSeconds\": 2 },\n  \"endpoints\": [\n    {\n      \"id\": \"custom\",\n      \"name\": \"Anrop enligt API-portalen\",\n      \"description\": \"Sökvägen relativt https://api.boverket.se/energideklarationer och eventuella frågeparametrar, enligt dokumentationen i portalen.\",\n      \"method\": \"GET\",\n      \"path\": \"/{path}\",\n      \"params\": [\n        { \"name\": \"path\", \"in\": \"path\", \"label\": \"Sökväg\", \"type\": \"string\", \"required\": true, \"raw\": true, \"example\": \"v2/energideklarationer\" },\n        { \"name\": \"query\", \"in\": \"query\", \"label\": \"Frågeparametrar\", \"type\": \"querylines\", \"example\": \"kommun=0180\" }\n      ],\n      \"response\": { \"format\": \"json\" },\n      \"dataset\": { \"name\": \"Boverket {path}\" }\n    }\n  ],\n  \"notes\": \"Högst 10 anrop per 2 sekunder och 1 500 per dag enligt Boverket.\",\n  \"i18n\": {\n    \"en\": {\"name\": \"Boverket energy performance certificates\", \"publisher\": \"Boverket (Swedish National Board of Housing, Building and Planning)\", \"description\": \"Energy performance certificates for buildings in Sweden through Boverket's API. Requires a subscription key from Boverket's API portal. The requests are described in the portal; give the path and parameters here.\", \"notes\": \"At most 10 requests per 2 seconds and 1,500 per day according to Boverket.\", \"auth\": {\"help\": \"Register in Boverket's API portal and subscribe to the API for energy performance certificates. The key is under your profile in the portal.\"}, \"endpoints\": {\"custom\": {\"name\": \"Request according to the API portal\", \"description\": \"The path relative to https://api.boverket.se/energideklarationer and any query parameters, as documented in the portal.\", \"params\": {\"path\": {\"label\": \"Path\"}, \"query\": {\"label\": \"Query parameters\"}}}}},\n    \"da\": {\"name\": \"Boverket energimærker\", \"publisher\": \"Boverket (Sveriges bolig-, bygge- og planmyndighed)\", \"description\": \"Energimærker for bygninger i Sverige via Boverkets API. Kræver en abonnementsnøgle fra Boverkets API-portal. Kaldene er beskrevet i portalen; angiv sti og parametre her.\", \"notes\": \"Højst 10 kald pr. 2 sekunder og 1 500 pr. dag ifølge Boverket.\", \"auth\": {\"help\": \"Registrér dig i Boverkets API-portal, og abonnér på API'et for energimærker. Nøglen findes under din profil i portalen.\"}, \"endpoints\": {\"custom\": {\"name\": \"Kald ifølge API-portalen\", \"description\": \"Stien i forhold til https://api.boverket.se/energideklarationer og eventuelle forespørgselsparametre ifølge dokumentationen i portalen.\", \"params\": {\"path\": {\"label\": \"Sti\"}, \"query\": {\"label\": \"Forespørgselsparametre\"}}}}},\n    \"nb\": {\"name\": \"Boverket energiattester\", \"publisher\": \"Boverket (Sveriges bolig-, bygg- og planmyndighet)\", \"description\": \"Energiattester for bygninger i Sverige via Boverkets API. Krever en abonnementsnøkkel fra Boverkets API-portal. Kallene er beskrevet i portalen; angi sti og parametere her.\", \"notes\": \"Høyst 10 kall per 2 sekunder og 1 500 per dag ifølge Boverket.\", \"auth\": {\"help\": \"Registrer deg i Boverkets API-portal, og abonner på API-et for energiattester. Nøkkelen finnes under profilen din i portalen.\"}, \"endpoints\": {\"custom\": {\"name\": \"Kall i henhold til API-portalen\", \"description\": \"Stien relativt til https://api.boverket.se/energideklarationer og eventuelle spørringsparametere i henhold til dokumentasjonen i portalen.\", \"params\": {\"path\": {\"label\": \"Sti\"}, \"query\": {\"label\": \"Spørringsparametere\"}}}}},\n    \"fi\": {\"name\": \"Boverket: energiatodistukset\", \"publisher\": \"Boverket (Ruotsin asunto-, rakennus- ja suunnitteluvirasto)\", \"description\": \"Ruotsin rakennusten energiatodistukset Boverketin rajapinnan kautta. Vaatii tilausavaimen Boverketin API-portaalista. Kutsut on kuvattu portaalissa; anna polku ja parametrit tässä.\", \"notes\": \"Enintään 10 kutsua 2 sekunnissa ja 1 500 päivässä Boverketin mukaan.\", \"auth\": {\"help\": \"Rekisteröidy Boverketin API-portaaliin ja tilaa energiatodistusten rajapinta. Avain on profiilisi alla portaalissa.\"}, \"endpoints\": {\"custom\": {\"name\": \"Kutsu API-portaalin mukaan\", \"description\": \"Polku suhteessa osoitteeseen https://api.boverket.se/energideklarationer ja mahdolliset kyselyparametrit portaalin dokumentaation mukaan.\", \"params\": {\"path\": {\"label\": \"Polku\"}, \"query\": {\"label\": \"Kyselyparametrit\"}}}}},\n    \"is\": {\"name\": \"Boverket: orkuvottorð\", \"publisher\": \"Boverket (Húsnæðis- og skipulagsstofnun Svíþjóðar)\", \"description\": \"Orkuvottorð bygginga í Svíþjóð gegnum vefþjónustu Boverket. Krefst áskriftarlykils frá API-gátt Boverket. Köllunum er lýst í gáttinni; gefðu upp slóð og breytur hér.\", \"notes\": \"Að hámarki 10 köll á 2 sekúndum og 1 500 á dag samkvæmt Boverket.\", \"auth\": {\"help\": \"Skráðu þig í API-gátt Boverket og gerstu áskrifandi að vefþjónustunni fyrir orkuvottorð. Lykillinn er undir sniðinu þínu í gáttinni.\"}, \"endpoints\": {\"custom\": {\"name\": \"Kall samkvæmt API-gáttinni\", \"description\": \"Slóðin miðað við https://api.boverket.se/energideklarationer og fyrirspurnarbreytur eftir þörfum, samkvæmt skjölun gáttarinnar.\", \"params\": {\"path\": {\"label\": \"Slóð\"}, \"query\": {\"label\": \"Fyrirspurnarbreytur\"}}}}}\n  }\n}\n");
